def link(href,label,cls='text-link',external=False):
 return f'<a class="{cls}" href="{href}"'+(' target="_blank" rel="noopener"' if external else '')+f'>{label} <span aria-hidden="true">↗</span></a>'

def layout(title,active,body,path='/'):
 nav=''.join(f'<a href="{url}"'+(' aria-current="page"' if name==active else '')+f'>{name}</a>' for name,url in [('Home','/'),('Portfolio','/portfolio/'),('Résumé','/resume/'),('Contact','/contact/')])
 desc='Jyoti Bhadrashetti, Construction Manager. Multifamily housing in Seattle and earlier architecture and interior projects in Dubai and Mumbai.'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | Jyoti Bhadrashetti</title><meta name="description" content="{desc}"><meta name="theme-color" content="#053369"><meta property="og:title" content="{escape(title)} | Jyoti Bhadrashetti"><meta property="og:description" content="{desc}"><meta property="og:image" content="{ORIGIN}/assets/jyoti-bhadrashetti.jpeg"><link rel="canonical" href="{ORIGIN}{path}"><link rel="icon" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/fonts.css"><link rel="stylesheet" href="/styles.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="wrap"><a class="brand" href="/" aria-label="Jyoti Bhadrashetti home"><span class="monogram">JB</span><span class="brand-name">Jyoti Bhadrashetti</span></a><nav aria-label="Main navigation">{nav}</nav></header><main id="main">{body}</main><footer class="wrap"><span>Jyoti M. Bhadrashetti</span><span>Construction Manager · LEED AP BD+C</span></footer></body></html>'''

def write(path,title,active,body):
 dest=ROOT/path.strip('/')/'index.html' if path!='/' else ROOT/'index.html'
 dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(layout(title,active,body,path))

